label("$B$",B,B);
label("$C$",C,C);
label("$D$",D,1.6*(W+0.3*SW));
label("$E$",Ep,SW);
label("$F$",F,E);
int i;
for(i=0;i<=5;++i)

{

draw(dir(60*i)--dir(60*(i+1)));

}
